# Hand-written general-knowledge questions, from Microsoft's Excel help.
# Each: (skill, league tier 5 easiest … 0 the top, topic, question, answer,
# [three wrong answers], Titan skill). Titan skill: the top tier's skill it
# belongs to (single = dynamic arrays, lambda = LAMBDA/names, speed = the rest).
T = []
def q(skill, tier, topic, question, answer, wrong, titan="speed"):
    assert len(wrong) == 3 and answer not in wrong, question
    T.append((skill, tier, topic, question, answer, wrong, titan))

